const now = new Date();
const start = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - 1, 1));
const end = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 0));
const ymd = (d) => d.toISOString().slice(0, 10);

return [{
  json: {
    start_date: ymd(start),
    end_date: ymd(end),
  },
}];

function collect(nodeName) {
  const items = $(nodeName).all().map((i) => i.json);
  if (items.length === 1 && Array.isArray(items[0])) return items[0];
  return items.filter((x) => x && typeof x === 'object' && !Array.isArray(x));
}

const period = $('Prepare Last Month').first().json;
const connectors = collect('Get Connectors');

if (!connectors.length) {
  return [{
    json: {
      _empty: true,
      start_date: period.start_date,
      end_date: period.end_date,
      message: 'No connectors found.',
    },
  }];
}

return connectors.map((c) => ({
  json: {
    start_date: period.start_date,
    end_date: period.end_date,
    connector_id: c.id,
    username: c.username,
    carrier: c.carrier,
    carrier_display_name: c.carrier_display_name || c.carrier,
    connector_group_id: c.company_id,
    connector_group_name: c.company_name || '',
    enabled: c.enabled,
    status: c.status,
  },
}));

const connector = $('Expand Connectors').item.json;

if (connector._empty) {
  return [{
    json: {
      period: {
        start_date: connector.start_date,
        end_date: connector.end_date,
      },
      connector_count: 0,
      invoice_count: 0,
      connectors: [],
      note: connector.message,
    },
  }];
}

const response = $input.first().json;
const invoices = Array.isArray(response.invoices)
  ? response.invoices
  : Array.isArray(response)
    ? response
    : [];

const seen = new Set();
let invoiceCount = 0;
for (const inv of invoices) {
  const key = [inv.credential_id, inv.invoice_number, inv.invoice_date].join('|');
  if (seen.has(key)) continue;
  seen.add(key);
  invoiceCount += 1;
}

return [{
  json: {
    start_date: connector.start_date,
    end_date: connector.end_date,
    connector_id: connector.connector_id,
    username: connector.username,
    carrier: connector.carrier,
    carrier_display_name: connector.carrier_display_name,
    connector_group_id: connector.connector_group_id,
    connector_group_name: connector.connector_group_name,
    invoice_count: invoiceCount,
  },
}];

const rows = $input.all().map((i) => i.json);

if (rows.length === 1 && rows[0].connectors) {
  return [{ json: rows[0] }];
}

const period = rows[0] || {};
const connectors = rows
  .map((r) => ({
    connector_id: r.connector_id,
    username: r.username,
    carrier: r.carrier,
    carrier_display_name: r.carrier_display_name,
    connector_group_id: r.connector_group_id,
    connector_group_name: r.connector_group_name,
    invoice_count: r.invoice_count || 0,
  }))
  .sort((a, b) => b.invoice_count - a.invoice_count);

const invoiceCount = connectors.reduce((sum, c) => sum + c.invoice_count, 0);

return [{
  json: {
    period: {
      start_date: period.start_date,
      end_date: period.end_date,
    },
    connector_count: connectors.length,
    invoice_count: invoiceCount,
    connectors,
  },
}];
